  const adminAchievementBackgroundData='data:image/jpeg;base64,';
  const adminAchievementLogoData='data:image/png;base64,';
  function loadAchievementImage(source){return new Promise(resolve=>{
    if(!source){resolve(null);return}
    const requested=String(source),isLogo=/^(?:\.\/)?logo\.png(?:[?#].*)?$/i.test(requested),isBg=/^(?:\.\/)?bg\.jpg(?:[?#].*)?$/i.test(requested);
    if(location.protocol==='file:'){
      if(isLogo)source=adminAchievementLogoData;
      else if(isBg)source=adminAchievementBackgroundData;
    }else{
      if(isLogo)source='logo.png?achievement='+Date.now();
      if(isBg)source='bg.jpg?achievement='+Date.now();
    }
    const image=new Image();let finished=false;
    const finish=value=>{if(finished)return;finished=true;clearTimeout(timeout);image.onload=null;image.onerror=null;resolve(value)};
    const timeout=setTimeout(()=>finish(null),8000);
    try{
      const resolved=new URL(source,document.baseURI);
      if(/^https?:$/i.test(resolved.protocol)&&resolved.origin!==location.origin)image.crossOrigin='anonymous';
      source=resolved.href
    }catch{}
    image.decoding='async';image.onload=()=>finish(image);image.onerror=()=>finish(null);image.src=source;
    if(image.complete&&image.naturalWidth)finish(image)
  })}
  function achievementCanvasSafeImage(image){if(!image)return null;try{const test=document.createElement('canvas');test.width=2;test.height=2;const c=test.getContext('2d');c.drawImage(image,0,0,2,2);test.toDataURL('image/png');return image}catch(error){console.warn('Achievement image skipped because it cannot be exported:',error);return null}}
  function achievementFontSize(text){const length=String(text).length;if(length<=6)return 178;if(length<=8)return 154;if(length<=10)return 132;if(length<=12)return 112;return 96}
  function roundRectPath(ctx,x,y,w,h,r){const radius=Math.min(r,w/2,h/2);ctx.beginPath();ctx.moveTo(x+radius,y);ctx.arcTo(x+w,y,x+w,y+h,radius);ctx.arcTo(x+w,y+h,x,y+h,radius);ctx.arcTo(x,y+h,x,y,radius);ctx.arcTo(x,y,x+w,y,radius);ctx.closePath()}
  async function downloadTotalDownloadsAchievement(button){
    const total=users.reduce((sum,user)=>sum+Number(user.downloads||0),0),formatted=total.toLocaleString('en-US'),snapshot=new Date().toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'});
    const original=button?.innerHTML;if(button){button.disabled=true;button.innerHTML='<span>…</span>'}
    try{
      const canvas=document.createElement('canvas');canvas.width=1200;canvas.height=1200;const ctx=canvas.getContext('2d');
      const [loadedBg,loadedLogo]=await Promise.all([loadAchievementImage('bg.jpg'),loadAchievementImage('logo.png')]);
      const background=achievementCanvasSafeImage(loadedBg),logo=achievementCanvasSafeImage(loadedLogo);

      if(background){
        const scale=Math.max(canvas.width/background.naturalWidth,canvas.height/background.naturalHeight);
        const w=background.naturalWidth*scale,h=background.naturalHeight*scale;
        ctx.drawImage(background,(canvas.width-w)/2,(canvas.height-h)/2,w,h);
      }else{
        const fallback=ctx.createLinearGradient(0,0,1200,1200);
        fallback.addColorStop(0,'#053766');fallback.addColorStop(1,'#0d82bd');
        ctx.fillStyle=fallback;ctx.fillRect(0,0,1200,1200);
      }

      /* subtle dark wash only to keep every white label readable over bg.jpg */
      ctx.fillStyle='rgba(0,0,0,.14)';ctx.fillRect(0,0,1200,1200);
      ctx.strokeStyle='rgba(255,255,255,.34)';ctx.lineWidth=2;roundRectPath(ctx,54,54,1092,1092,44);ctx.stroke();

      if(logo){
        ctx.save();ctx.beginPath();ctx.arc(126,128,42,0,Math.PI*2);ctx.clip();ctx.drawImage(logo,84,86,84,84);ctx.restore()
      }else{
        ctx.fillStyle='rgba(255,255,255,.96)';ctx.beginPath();ctx.arc(126,128,42,0,Math.PI*2);ctx.fill()
      }

      ctx.textBaseline='middle';ctx.textAlign='left';ctx.fillStyle='#fff';
      ctx.font='800 39px Poppins, Arial, sans-serif';ctx.fillText('Watermark Pro',194,128);

      ctx.font='800 22px Poppins, Arial, sans-serif';ctx.fillText('THANK YOU',84,258);

      ctx.textAlign='center';ctx.font='800 '+achievementFontSize(formatted)+'px Poppins, Arial, sans-serif';
      ctx.fillText(formatted,600,565,1000);
      ctx.font='800 34px Poppins, Arial, sans-serif';ctx.fillText('TOTAL DOWNLOADS',600,715);

      ctx.strokeStyle='rgba(255,255,255,.42)';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(84,835);ctx.lineTo(1116,835);ctx.stroke();

      ctx.textAlign='left';ctx.font='700 18px Poppins, Arial, sans-serif';ctx.fillStyle='#fff';ctx.fillText('DATA AS OF',84,914);
      ctx.font='700 31px Poppins, Arial, sans-serif';ctx.fillText(snapshot,84,960);

      const blob=await new Promise((resolve,reject)=>{
        try{canvas.toBlob(value=>value?resolve(value):reject(new Error('Unable to create image')),'image/png')}
        catch(error){reject(error)}
      });
      const url=URL.createObjectURL(blob),link=document.createElement('a');
      link.href=url;link.download='watermark-pro-total-downloads-'+String(total)+'-'+new Date().toISOString().slice(0,10)+'.png';
      document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);
      showToast('Total Downloads image downloaded');
    }catch(error){
      console.error('Total Downloads achievement failed:',error);
      showToast(error?.message||'Unable to create image')
    }finally{if(button){button.disabled=false;button.innerHTML=original}}
  }
  function renderOverview(){const root=document.querySelector('[data-admin-section="overview"]');if(!root)return;const stats=root.querySelectorAll('.admin-stat strong'),active=users.filter(user=>planFor(user.uid)==='pro'),expiring=active.filter(user=>Number(subscriptions[user.uid]?.expiresAt||0)-Date.now()<=7*86400000),downloads=users.reduce((sum,user)=>sum+Number(user.downloads||0),0);if(stats[0])stats[0].textContent=users.length.toLocaleString();if(stats[1])stats[1].textContent=active.length.toLocaleString();if(stats[2])stats[2].textContent=expiring.length.toLocaleString();if(stats[3]){stats[3].textContent=downloads.toLocaleString();const stat=stats[3].closest('.admin-stat');if(stat){stat.classList.add('admin-download-achievement-stat');let button=stat.querySelector('.admin-download-achievement-btn');if(!button){button=document.createElement('button');button.type='button';button.className='admin-download-achievement-btn';button.setAttribute('aria-label','Download Total Downloads image');button.title='Download Total Downloads image';button.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3v12m0 0 4-4m-4 4-4-4M5 21h14"/></svg><span>Download achievement</span>';button.onclick=()=>downloadTotalDownloadsAchievement(button);stat.appendChild(button)}}}const table=root.querySelector('.admin-table');if(!table)return;table.innerHTML='<div class="admin-row-overview admin-head"><div class="ov-user">User</div><div class="ov-dl">Downloads</div><div class="ov-plan">Plan</div><div class="status-right">Status</div></div>'+[...users].sort((a,b)=>Number(b.downloads||0)-Number(a.downloads||0)).slice(0,20).map(user=>{const plan=planFor(user.uid),days=plan==='pro'?Math.ceil((Number(subscriptions[user.uid].expiresAt)-Date.now())/86400000):0,status=plan==='pro'?(days<=7?'expiring':'active'):plan==='expired_free'?'expired':'free',label=plan==='pro'?(days<=7?'EXPIRING':'ACTIVE'):plan==='expired_free'?'EXPIRED':'FREE',badge=plan==='pro'?cloneBadge():'';return '<div class="admin-row-overview"><div class="ov-user admin-user">'+avatar(user)+'<div class="admin-name"><span>'+safe(mobileName(user.name||'User'))+'</span>'+(badge?badge.replace('class="verified-badge clickable"','class="verified-badge clickable" data-verified-uid="'+safe(user.uid)+'"'):badge)+'</div></div><div class="ov-dl">'+compact(Number(user.downloads||0))+'</div><div class="ov-plan">'+(plan==='pro'?'Pro':'Free')+'</div><div class="status-right"><span class="admin-status '+status+'">'+label+'</span></div></div>'}).join('');bindBadges(table,Object.fromEntries(users.map(user=>[user.uid,user])))}
